]

/** A TypeSafe-shaped answer to the first request. */
const wideAnswer = (
  choice: string,
  probabilities: Record<string, number> | undefined,
  gate: Partial<Record<keyof typeof GATE_QUESTIONS, number>> = {},
) => {
